p('A relational database project for managing charging infrastructure, reservations, energy consumption and payment records.')
page('01  /  OVERVIEW','Abstract and project scope')
p('The EV Charging Station Management System organizes the complete charging record lifecycle in MySQL. Six related tables distinguish drivers, station locations, individual chargers, reservations, charging sessions and payments. Keys and constraints preserve relationships, while stored procedures coordinate booking, tariff capture, completion and billing. Views and demonstration queries expose booking history, consumption and revenue.')
p('The project is a SQL focused academic implementation operated through MySQL Workbench. It does not include a deployed application, live charging hardware or payment gateway. Source inspection establishes the implemented structure; saved test summaries are historical evidence and were not rerun for this report. The design illustrates normalization, joins, aggregation and transaction processing while retaining clearly documented implementation limits.')
h('Problem and objectives')
p('A reservation identifies the intended charger and time interval; a session records actual charging; a payment records the invoice and settlement state. Keeping these facts separate prevents station and customer details from being repeatedly stored in every transaction. The objectives are consistent identities, traceable reservations, session based pricing and useful SQL reports.')
table(['Requirement','Database response'],[['Manage drivers and infrastructure','users, stations and chargers'],['Reserve and record charging','bookings and charging_sessions'],['Calculate and record payment','Stored rate, rounded amount and payments'],['Inspect activity','Views, joins and aggregate reports']])
h('Report navigation')
table(['Page','Topic'],[['3','Architecture and operating model'],['4','Complete entity relationship diagram'],['5','Keys, domains and normalization'],['6','Setup and usage'],['7','Booking to payment walkthrough'],['8','Selected SQL queries'],['9','Procedures, triggers and reporting'],['10','Results, limitations and conclusion']])
page('02  /  SYSTEM DESIGN','Architecture and workflow')
h('Database centered architecture')
table(['Layer','Responsibility','Project component'],[['Operator interface','Execute SQL and inspect result grids','MySQL Workbench or mysql client'],['Business operations','Validate and coordinate changes','Stored procedures and transactions'],['Persistence','Store records and enforce constraints','MySQL InnoDB tables'],['Reporting','Combine and summarize stored facts','Views and demonstration queries']])
h('The charging lifecycle')
table(['Stage','Operation','Result'],[['1  Select','Find an ACTIVE charger and free interval','Candidate charging slot'],['2  Reserve','sp_book_charger_slot','CONFIRMED booking'],['3  Start','sp_start_charging_session','IN_PROGRESS session and rate snapshot'],['4  Complete','sp_complete_charging_session','Energy recorded and pending invoice'],['5  Settle','sp_process_payment','Payment state and timestamp'],['6  Review','Views or revenue procedure','Joined activity and financial results']])
h('Operational status and availability')
p('ACTIVE means the charger is operational. It does not mean every time slot is free. The booking procedure checks both charger status and overlap with pending or confirmed bookings. Two intervals overlap when existing.start < requested.end and requested.start < existing.end. Adjacent intervals are accepted.')
h('Environment and quality requirements')
p('The source targets MySQL with InnoDB and uses MySQL Workbench for demonstration on Windows. Data integrity depends on keys, check constraints and procedure validation. Six indexes support common search patterns. Exact server version, concurrency behavior and performance were not independently verified in this report. A restricted database account and backups are required for any real deployment.')
page('03  /  DATA MODEL','Complete entity relationship diagram')
